// Détermination du communiqué attendu.
//
// Le communiqué publié au mois M porte sur le mois M−1 : on vise donc toujours
// le mois révolu, jamais le mois courant.
//
// CONFORMITÉ, vérifiée le 23.08.2026 sur le fichier robots.txt de la source :
// l'agent générique « * » est autorisé, et plusieurs robots d'indexation de
// modèles y sont nommément interdits. Le dispositif s'annonce donc sous un
// agent propre, à usage académique déclaré, et ne se fait pas passer pour un
// navigateur. Il ne relève d'aucune des interdictions nominatives.
const MOIS_EN = ['January','February','March','April','May','June',
                 'July','August','September','October','November','December'];
const auj = new Date();
const premier = new Date(Date.UTC(auj.getUTCFullYear(), auj.getUTCMonth(), 1));
const precedent = new Date(premier.getTime() - 86400000);
const annee = precedent.getUTCFullYear();
const mois = precedent.getUTCMonth();          // 0-11
const periode = annee + '-' + String(mois + 1).padStart(2, '0');
return [{ json: {
  run_id: $('Ouvrir le run').first().json.run_id,
  periode,
  url: 'https://www.acea.auto/files/Press_release_car_registrations_'
       + MOIS_EN[mois] + '_' + annee + '.pdf'
} }];

// Le communiqué est-il paru ?
//
// La détection ne fait qu'une chose : constater qu'un document EXISTE. Elle ne
// l'extrait pas, ne l'interprète pas, et n'écrit aucune valeur au registre —
// elle inscrit une entrée en FILE DE VÉRIFICATION, au statut « a_verifier ».
// L'inscription au registre reste conditionnée à la chaîne composite
// multi-modèles ET à la validation humaine (§ 10.4). Un document détecté n'est
// pas un document lu.
const t = $('Cibler le communiqué attendu').first().json;
const r = $json;
const code = r.statusCode ?? (r.error && r.error.httpCode) ?? 0;
const type = String((r.headers && (r.headers['content-type'] || r.headers['Content-Type'])) || '');
const dispo = String(code) === '200' && /pdf/i.test(type);
return [{ json: { ...t, disponible: dispo, code_http: String(code), type_contenu: type.slice(0, 60) } }];
